// Sokoban: push crates onto goals. Levels are generated by reverse-pulling crates from their goals, so they are always
// solvable. Undo (Z/U), restart (R), move counter, growing levels, ice patches (mods: ice) and fog (mods: dark).
import { background, Bag, byDiff, createStage, emoji, keys, loop, Particles, pointer, roundRect, Shake, isTouch, swipe, text, vpad, type Engine } from '../kit'
import { genSokoban, move, SDIR, type Sok } from '../logic/sokoban'

let W = 800
let H = 450

interface Snap {
  boxes: number[]
  player: number
  moves: number
  pushes: number
}

const engine: Engine = {
  start(env) {
    const { theme: t, mods } = env
    const hr = env.host.getBoundingClientRect()
    if (hr.height > hr.width * 1.15) {
      W = 450
      H = 800
    } else {
      W = 800
      H = 450
    }
    const st = createStage(env.host, W, H)
    const c = st.ctx
    const k = keys()
    const bag = new Bag()
    const fx = new Particles()
    const shake = new Shake()
    const ptr = pointer(st)
    const ice = mods.has('ice') || /\bice|icy|slide|frozen\b/i.test(env.name)
    const dark = mods.has('dark') || /\b(dark|shadow|night|smuggler)\b/i.test(env.name)
    const levels = byDiff(env, 6, 8, 10)
    let level = 1
    let score = 0
    let lvl!: Sok
    let boxes: number[] = []
    let player = 0
    let moves = 0
    let pushes = 0
    let hist: Snap[] = []
    let cs = 48
    let ox = 0
    let oy = 0
    let rb: { x: number; y: number }[] = []
    let rp = { x: 0, y: 0 }
    let face = 1
    let cool = 0
    let solvedT = 0
    let msg = ''
    let msgT = 0
    let over = false
    let tt = 0
    let bump = 0
    const queue: number[] = []

    const build = () => {
      const w = Math.min(ice ? 8 : 11, 6 + Math.floor(level / 2) + byDiff(env, 0, 0, 1))
      const h = Math.min(ice ? 7 : 9, 5 + Math.floor((level + 1) / 2))
      const nb = Math.min(ice ? 3 : 7, 1 + Math.floor((level + 1) * 0.75) + byDiff(env, -1, 0, 1))
      lvl = genSokoban(env.rng, { w, h, boxes: Math.max(1, nb), ice })
      boxes = lvl.boxes.slice()
      player = lvl.player
      moves = pushes = 0
      hist = []
      cs = Math.min(60, Math.floor((W - 40) / w), Math.floor((H - 50) / h))
      ox = Math.round((W - w * cs) / 2)
      oy = Math.round((H - h * cs) / 2) + 6
      rb = boxes.map((b) => pos(b))
      rp = pos(player)
      solvedT = 0
      hud()
    }
    const pos = (i: number) => ({ x: i % lvl.w, y: (i / lvl.w) | 0 })
    const px = (i: number) => ({ x: ox + ((i % lvl.w) + 0.5) * cs, y: oy + (((i / lvl.w) | 0) + 0.5) * cs })
    const hud = () => {
      env.score(score)
      const on = boxes.filter((b) => lvl.goals.includes(b)).length
      env.status(`Level ${level}/${levels} · ${on}/${boxes.length} · ${moves} moves`)
    }

    const doMove = (d: number) => {
      if (solvedT > 0 || over) return
      face = d === 3 ? -1 : d === 1 ? 1 : face
      const r = move(lvl, boxes, player, d)
      if (!r) {
        bump = 0.12
        env.sfx('hit')
        return
      }
      hist.push({ boxes, player, moves, pushes })
      boxes = r.boxes
      player = r.player
      moves++
      if (r.pushed) {
        pushes++
        env.sfx('click')
        const on = boxes.filter((b) => lvl.goals.includes(b)).length
        const p = px(player)
        fx.burst(p.x + SDIR[d].dx * cs * 0.5, p.y + SDIR[d].dy * cs * 0.5, t.fg, 5, 70, 2)
        if (on === boxes.length) {
          done()
        } else if (boxes.some((b) => lvl.goals.includes(b))) env.sfx('point')
      } else env.sfx('move')
      hud()
    }

    const done = () => {
      solvedT = 1.4
      env.sfx('win')
      shake.kick(4)
      for (const b of boxes) {
        const p = px(b)
        fx.burst(p.x, p.y, t.good, 16, 200, 3)
        fx.burst(p.x, p.y, t.accent, 10, 150, 3)
      }
      score += Math.max(50, 100 * level + 200 - moves * 2)
      msg = 'Level clear!'
      msgT = 1.4
      hud()
    }

    const undo = () => {
      const s = hist.pop()
      if (!s || solvedT > 0) return
      boxes = s.boxes
      player = s.player
      moves = s.moves
      pushes = s.pushes
      env.sfx('power')
      hud()
    }
    const restart = () => {
      if (solvedT > 0 || over) return
      boxes = lvl.boxes.slice()
      player = lvl.player
      moves = pushes = 0
      hist = []
      env.sfx('click')
      hud()
    }
    k.onKey((e) => {
      if (e.code === 'KeyR') restart()
      if (e.code === 'KeyU' || e.code === 'Backspace') undo()
    })
    bag.add(swipe(st.canvas, (d) => queue.push({ up: 0, right: 1, down: 2, left: 3 }[d])))
    ptr.onDown((p) => {
      if (p.y < 40 && p.x > W - 180) return restart()
      const cx = Math.floor((p.x - ox) / cs)
      const cy = Math.floor((p.y - oy) / cs)
      const q = pos(player)
      const dx = cx - q.x
      const dy = cy - q.y
      if (Math.abs(dx) + Math.abs(dy) === 1) queue.push(dx === 1 ? 1 : dx === -1 ? 3 : dy === 1 ? 2 : 0)
    })
    const vp = vpad(env.host, k, 'dpad', [{ action: 'a', label: '↶' }])

    build()
    const dirs = ['up', 'right', 'down', 'left']

    const update = (dt: number) => {
      tt += dt
      fx.update(dt)
      shake.update(dt)
      bump = Math.max(0, bump - dt)
      msgT -= dt
      const kk = Math.min(1, dt * 22)
      const pp = pos(player)
      rp.x += (pp.x - rp.x) * kk
      rp.y += (pp.y - rp.y) * kk
      boxes.forEach((b, i) => {
        const q = pos(b)
        rb[i].x += (q.x - rb[i].x) * kk
        rb[i].y += (q.y - rb[i].y) * kk
      })
      if (solvedT > 0) {
        solvedT -= dt
        if (solvedT <= 0) {
          if (level >= levels) {
            over = true
            env.end({ score, won: true, text: `Cleared all ${levels} warehouses` })
          } else {
            level++
            build()
          }
        }
        return
      }
      if (over) return
      cool -= dt
      if (k.hit('a')) undo()
      if (cool > 0) return
      let d = queue.length ? queue.shift()! : -1
      if (d < 0) for (let i = 0; i < 4; i++) if (k.hit(dirs[i])) d = i
      if (d < 0) for (let i = 0; i < 4; i++) if (k.down(dirs[i])) d = i
      if (d >= 0) {
        doMove(d)
        cool = 0.115
      }
    }

    const draw = () => {
      c.save()
      background(c, W, H, t, 40, env.seed)
      shake.apply(c)
      const { w, h } = lvl
      for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
        const i = y * w + x
        const X = ox + x * cs
        const Y = oy + y * cs
        if (lvl.wall[i]) {
          const edge = x === 0 || y === 0 || x === w - 1 || y === h - 1
          roundRect(c, X + 1, Y + 1, cs - 2, cs - 2, 6, edge ? 'rgba(20,20,40,.55)' : t.blocks[0], edge ? 'rgba(0,0,0,.3)' : 'rgba(0,0,0,.35)', 1.5)
          if (!edge) {
            c.fillStyle = 'rgba(0,0,0,.3)'
            c.fillRect(X + 3, Y + cs - 9, cs - 6, 6)
            c.fillStyle = 'rgba(255,255,255,.12)'
            c.fillRect(X + 4, Y + 4, cs - 8, 4)
          }
          continue
        }
        c.fillStyle = (x + y) & 1 ? 'rgba(255,255,255,.07)' : 'rgba(255,255,255,.035)'
        c.fillRect(X, Y, cs, cs)
        if (lvl.ice[i]) {
          const g = c.createLinearGradient(X, Y, X + cs, Y + cs)
          g.addColorStop(0, 'rgba(150,220,255,.45)')
          g.addColorStop(1, 'rgba(210,245,255,.2)')
          c.fillStyle = g
          c.fillRect(X, Y, cs, cs)
          c.strokeStyle = 'rgba(255,255,255,.5)'
          c.lineWidth = 2
          c.beginPath()
          c.moveTo(X + cs * 0.2, Y + cs * 0.35)
          c.lineTo(X + cs * 0.45, Y + cs * 0.15)
          c.stroke()
        }
      }
      for (const [gi, g] of lvl.goals.entries()) {
        const p = px(g)
        c.save()
        c.strokeStyle = t.accent2
        c.shadowColor = t.accent2
        c.shadowBlur = 10
        c.lineWidth = 3
        c.setLineDash([6, 5])
        c.lineDashOffset = -tt * 10
        c.beginPath()
        c.arc(p.x, p.y, cs * 0.34, 0, 7)
        c.stroke()
        c.restore()
        c.globalAlpha = 0.35
        emoji(c, t.items[gi % t.items.length], p.x, p.y, cs * 0.4)
        c.globalAlpha = 1
      }
      boxes.forEach((b, i) => {
        const x = ox + (rb[i].x + 0.5) * cs
        const y = oy + (rb[i].y + 0.5) * cs
        const on = lvl.goals.includes(b)
        const s = cs * 0.84
        c.save()
        if (on) {
          c.shadowColor = t.good
          c.shadowBlur = 16
        }
        roundRect(c, x - s / 2, y - s / 2, s, s, 8, on ? t.good : t.blocks[(i + 1) % t.blocks.length], 'rgba(0,0,0,.45)', 2)
        c.restore()
        c.strokeStyle = 'rgba(0,0,0,.25)'
        c.lineWidth = 2
        c.strokeRect(x - s * 0.3, y - s * 0.3, s * 0.6, s * 0.6)
        emoji(c, t.items[i % t.items.length], x, y, cs * 0.5)
      })
      const hx = ox + (rp.x + 0.5) * cs + (bump > 0 ? Math.sin(bump * 80) * 2 : 0)
      const hy = oy + (rp.y + 0.5) * cs + Math.sin(tt * 6) * 1.2
      c.fillStyle = 'rgba(0,0,0,.3)'
      c.beginPath()
      c.ellipse(hx, hy + cs * 0.34, cs * 0.28, cs * 0.09, 0, 0, 7)
      c.fill()
      c.save()
      c.translate(hx, hy)
      c.scale(face, 1)
      emoji(c, t.hero, 0, 0, cs * 0.82)
      c.restore()
      fx.draw(c)
      if (dark) {
        const g = c.createRadialGradient(hx, hy, cs * 1.4, hx, hy, cs * 4.2)
        g.addColorStop(0, 'rgba(0,0,8,0)')
        g.addColorStop(1, 'rgba(0,0,8,.93)')
        c.fillStyle = g
        c.fillRect(-20, -20, W + 40, H + 40)
      }
      c.restore()
      text(c, isTouch() ? '↻ TAP: RESTART' : 'Z undo · R restart', W - 12, 16, { size: 9, color: t.fg, align: 'right' })
      if (tt < 2.8) {
        c.globalAlpha = tt < 2.2 ? 1 : 1 - (tt - 2.2) / 0.6
        const by0 = W < 600 ? 22 : H - 52
        roundRect(c, W / 2 - Math.min(300, W / 2 - 6), by0, Math.min(600, W - 12), 40, 10, 'rgba(0,0,0,.55)')
        text(c, env.name.length > 34 ? env.name.slice(0, 33) + '…' : env.name, W / 2, by0 + 12, { size: W < 600 ? 9 : 12, color: t.accent })
        text(c, ice ? 'ARROWS / SWIPE   ice makes you slide!' : W < 600 ? 'SWIPE / D-PAD   push crates onto goals' : 'ARROWS / WASD / SWIPE   push every crate onto a goal', W / 2, by0 + 30, { size: W < 600 ? 6 : 8, color: t.fg })
        c.globalAlpha = 1
      }
      if (solvedT > 0) {
        c.fillStyle = 'rgba(0,0,0,.4)'
        c.fillRect(0, H / 2 - 36, W, 72)
        text(c, msg, W / 2, H / 2, { size: 26, color: t.good, shadow: t.good })
      }
    }

    const lp = loop(update, draw)
    return {
      pause: (p) => lp.pause(p),
      destroy() {
        lp.stop()
        vp()
        k.dispose()
        ptr.dispose()
        bag.dispose()
        st.dispose()
      },
    }
  },
}

export default engine
